// PURE LOGIC — no secrets, no environment reads, no httpRequest. Validate + parse only.
const ALLOWED = ['https://www.bznsflowai.com', 'https://bznsflowai.com'];
const MAX_CHARS = 800;
const injectionPattern = /ignore (previous|all|above)|system prompt|you are now|act as|jailbreak|disregard|(repeat|reveal|show|print|output|give me|what (are|were)|tell me).{0,30}(instruction|prompt|rules|system message|configuration|guidelines)|verbatim|above this (conversation|chat)|your (initial |original )?(instructions|prompt)/i;

const root = $input.first().json;
const headers = root.headers || {};
const origin = headers.origin || headers.Origin || '';
const corsOrigin = ALLOWED.includes(origin) ? origin : '';
const method = (root.method || 'POST').toUpperCase();
const xff = headers['x-forwarded-for'] || headers['X-Forwarded-For'] || '';
const ip = (String(xff).split(',')[0] || '').trim() || 'unknown';

if (method === 'OPTIONS') {
  return [{ json: { _preflight: true, _cors: corsOrigin } }];
}

const body = root.body || {};
const rawMsg = typeof body.message === 'string' ? body.message : '';
let sessionId = typeof body.sessionId === 'string' ? body.sessionId : '';
if (!/^[A-Za-z0-9_:-]{6,80}$/.test(sessionId)) sessionId = '';
const message = rawMsg.trim();

let blocked = null;
if (!corsOrigin)                       blocked = { _status: 403, _reply: 'Forbidden origin.' };
else if (!sessionId)                   blocked = { _status: 400, _reply: 'Missing or invalid sessionId.' };
else if (!message)                     blocked = { _status: 400, _reply: 'Empty message.' };
else if (message.length > MAX_CHARS)   blocked = { _status: 400, _reply: 'Message too long.' };
else if (injectionPattern.test(message)) blocked = { _status: 200, _reply: 'أنا هنا لمساعدتك بخصوص BznsFlow فقط 😊 / I can only help with BznsFlow here.' };

if (blocked) {
  return [{ json: { _preflight: false, _blocked: true, _cors: corsOrigin, sessionId, handoff: false, ...blocked } }];
}

const now = new Date();
return [{ json: {
  _preflight: false,
  _blocked: false,
  _cors: corsOrigin,
  ip,
  sessionId,
  sessionKey: 'web:' + sessionId,
  message,
  _minute: now.toISOString().slice(0, 16),
  _day: now.toISOString().slice(0, 10)
} }];

// PURE LOGIC — decide if rate limited. Carry original guard fields forward.
const PER_IP_PER_MIN = 20;
const GLOBAL_PER_DAY = 1000; // aligned with Groq free-tier daily token budget; raise after upgrading Groq tier
const src = $('Guard & Validate').first().json;
const rl = $input.first().json;
const ipHits = Number(rl.ip_hits || 0);
const globalHits = Number(rl.global_hits || 0);

if (ipHits > PER_IP_PER_MIN) {
  return [{ json: { ...src, _blocked: true, _status: 429, _reply: 'شوي شوي 🙏 حاول بعد دقيقة / A bit fast — try again in a minute.', handoff: false } }];
}
if (globalHits > GLOBAL_PER_DAY) {
  return [{ json: { ...src, _blocked: true, _status: 429, _reply: 'الخدمة مشغولة حالياً، جرّب لاحقاً 🙏 / Service is busy, please try later.', handoff: false } }];
}
return [{ json: { ...src, _blocked: false } }];

// PURE LOGIC — build the LLM inputs for the AI Agent (Groq). No secrets.
// Persona source of record: web-chatbot/system-prompt-web-bznsflow.md
// Catalog source of record: web-chatbot/layla-knowledge-base.md (keyword-injected below, top 3 sections)
const src = $('Guard & Validate').first().json;
const row = $input.first().json;
const conversationId = row.conversation_id;
// history came back newest-first (LIMIT 20), reverse to chronological
let hist = row.history || [];
if (typeof hist === 'string') { try { hist = JSON.parse(hist); } catch (e) { hist = []; } }
hist = Array.isArray(hist) ? hist.slice().reverse() : [];
// The current user message is already persisted as the LAST 'user' turn in history
// (PG: Session + History inserts it before selecting). Drop that final turn so it is
// not duplicated: it becomes the Agent's `text` (user message); the rest is context.
let prior = hist.slice();
const currentMsg = src.message;
if (prior.length && prior[prior.length - 1].role === 'user' && prior[prior.length - 1].content === currentMsg) {
  prior = prior.slice(0, -1);
}
const historyText = prior
  .map(m => (m.role === 'user' ? 'Visitor' : 'Layla') + ': ' + m.content)
  .join('\n');

