const src = $('Build Prompt').first().json;
const resp = $input.first().json;
let reply = 'عذراً، صار خطأ بسيط 🙏 جرّب مرة ثانية / Sorry, a small glitch — please try again.';
let handoff = false, handoffContext = '';
try {
  // AI Agent puts the model text in `output`; fall back to common shapes just in case.
  const text = (resp && (resp.output || resp.text || (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content))) || '';
  const match = String(text).match(/\{[\s\S]*\}/);
  if (match) {
    const obj = JSON.parse(match[0]);
    reply = (obj.reply || '').toString().slice(0, 1200) || reply;
    handoff = obj.handoff === true;
    handoffContext = (obj.handoff_context || '').toString().slice(0, 300);
  } else if (text) {
    reply = String(text).slice(0, 1200);
  }
} catch (e) { /* keep friendly fallback; never leak error detail */ }
return [{ json: { ...src, reply, handoff, handoffContext } }];

// PURE LOGIC — on LLM (Groq) failure, produce a safe fallback reply so the caller
// still gets a 200 JSON (no hanging branch). No secrets.
const src = $('Build Prompt').first().json;
return [{ json: { ...src, reply: 'عذراً، صار خطأ بسيط 🙏 جرّب مرة ثانية / Sorry, a small glitch — please try again.', handoff: false, handoffContext: '' } }];

// Reconstruct the response payload from whichever LLM branch ran.
// Parse Reply (success) and LLM Error Fallback (error) both carry the same shape.
let src;
try { src = $('Parse Reply').first().json; if (!src || src.reply === undefined) src = null; } catch (e) { src = null; }
if (!src) { try { src = $('LLM Error Fallback').first().json; } catch (e) { src = null; } }
if (!src) { src = { reply: 'عذراً، صار خطأ بسيط 🙏 / Sorry, a small glitch.', sessionId: '', handoff: false, handoffContext: '', _cors: '' }; }
return [{ json: {
  reply: src.reply,
  sessionId: src.sessionId,
  handoff: src.handoff === true,
  handoff_context: src.handoffContext || '',
  _cors: src._cors || ''
} }];
